1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Quote: simplest case and base premiums ---
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result.results).toEqual([{ premium: 5 }]);
13	  });
14	  it("a plain sword → base premium 100 G + 10 G first insurance + 5 G fee = 115 G", () => {
15	    const result = runScenario({
16	      customer: { yearsWithMHPCO: 0 },
17	      steps: [
18	        {
19	          op: "quote",
20	          items: [
21	            { type: "sword", material: "steel", enchantment: 3, cursed: false },
22	          ],
23	        },
24	      ],
25	    });
26	
27	    expect(result.results).toEqual([{ premium: 115 }]);
28	  });
29	  it.todo("a plain amulet → base premium 60 G + 6 G first insurance + 5 G fee = 71 G");
30	  it.todo("a plain staff → base premium 80 G + 8 G first insurance + 5 G fee = 93 G");
31	  it.todo("a plain potion → base premium 40 G + 4 G first insurance + 5 G fee = 49 G");
32	  it.todo("a single rune → base premium 25 G + 2.5 G first insurance + 5 G fee = 33 G (rounded up)");
33	  it.todo("a single moonstone → base premium 25 G + 2.5 G first insurance + 5 G fee = 33 G (rounded up)");
34	
35	  // --- Components: block of 3 alike ---
36	  it.todo("2 runes → 50 G base premium");
37	  it.todo("3 runes → 60 G base premium (block applies)");
38	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
39	  it.todo("7 runes → 175 G base premium");
40	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
41	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
42	
43	  // --- Premium modifiers in isolation ---
44	  it.todo("cursed sword adds a 50 % risk surcharge on its own base premium (+50 G)");
45	  it.todo("sword with enchantment 5 adds a 30 % high-enchantment surcharge (+30 G)");
46	  it.todo("sword with enchantment 4 gets no high-enchantment surcharge");
47	  it.todo("cursed sword with enchantment 5 gets both surcharges (+50 G and +30 G)");
48	  it.todo("customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
49	  it.todo("customer with 1 year with MHPCO receives no loyalty discount");
50	  it.todo("a first insurance carries a 10 % initial assessment surcharge");
51	  it.todo("the second quote in a scenario receives a 15 % follow-up contract discount");
52	  it.todo("a 5 G processing fee is added to every premium");
53	
54	  // --- Modifier scope on multi-item policies ---
55	  it.todo("cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G → 210 G before further modifiers and fee");
56	  it.todo("item-specific modifiers apply per item; policy-wide modifiers apply to the policy base premium; the fee is added last");
57	
58	  // --- Rounding in MHPCO's favour ---
59	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
60	  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
61	
62	  // --- Integration examples ---
63	  it.todo("newcomer with a cursed sword (0 years, no previous contract) → premium 165 G");
64	  it.todo("long-standing customer's second contract, cursed sword enchantment 7 → premium 160 G");
65	
66	  // --- Claim: standard reimbursement ---
67	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
68	  it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G");
69	
70	  // --- Claim: special clauses ---
71	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
72	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
73	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
74	  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
75	
76	  // --- Claim: deductible per damage event ---
77	  it.todo("dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)");
78	
79	  // --- Claim: rounding ---
80	  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
81	
82	  // --- Claim: insurance sum and cap ---
83	  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
84	  it.todo("a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
85	  it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G (block discount affects the premium only)");
86	  it.todo("sword insured (cap 2000 G), two successive claims of 1500 G each → first payout 1400 G, remaining cap 600 G");
