91	  it.todo("two sword damage entries on a two-sword policy → each treated as a separate damage with its own deductible");
92	  it.todo("more damage entries of a type than the policy covers → the whole claim is rejected");
93	
94	  // --- Edge cases / errors ---
95	  it.todo("quote with an unknown item type (e.g. broomstick) → error");
96	  it.todo("claim referencing an item not part of the policy (amulet damaged when only a sword insured) → error");
97	  it.todo("claim referencing a damage entry with an unknown item type → error");
98	  it.todo("claim containing a damage entry with amount -200 → error");
99	
100	  // --- CLI contract ---
101	  it.todo("CLI reads a scenario from stdin and writes {results: [...]} to stdout in step order");
102	  it.todo("CLI writes premium for quote steps and payout + remainingCap for claim steps");
103	  it.todo("CLI exits with a non-zero status code and writes an error to stderr for an unknown item type, writing no results to stdout");
104	  it.todo("CLI exits with a non-zero status code and writes an error to stderr for an invalid claim");
105	});
